"use client"

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"
import { Button, buttonVariants } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/hooks/use-controllable-state"
import {
  GridColumns,
  GridContainer,
  GridSection,
} from "@/components/ui/grid-layout/grid-layout"
import { DEFAULT_LABELS } from "./config"
import { Auth04Panel } from "./org-panel"
import { createEmailSchema, createSlugSchema } from "./schemas"
import { Auth04EmailStep, Auth04PasswordStep, Auth04SsoStep } from "./steps"
import type { Auth04Props, Auth04Resolution, Auth04Step } from "./types"
import { useAsyncAction } from "./use-auth-form"

type SsoResolution = Extract<Auth04Resolution, { kind: "sso" }>

/** 企业 SSO 登录：先识别工作邮箱所属组织，再决定走企业身份还是账号密码。 */
function Auth04({
  onResolveDomain,
  onResolveOrg,
  onSsoSignIn,
  onPasswordSignIn,
  onSuccess,
  onAlternative,
  supportHref = "#",
  brand,
  labels: labelsProp,
  step: stepProp,
  defaultStep = "email",
  onStepChange,
  className,
  ...props
}: Auth04Props) {
  const text = { ...DEFAULT_LABELS, ...labelsProp }
  const [step, setStep] = useControllableState<Auth04Step>({
    prop: stepProp,
    defaultProp: defaultStep,
    onChange: onStepChange,
  })
  const [email, setEmail] = React.useState("")
  const [emailError, setEmailError] = React.useState("")
  // 邮箱经域名识别确认过；经组织标识进入时没有邮箱
  const [identified, setIdentified] = React.useState(false)
  const [orgOpen, setOrgOpen] = React.useState(false)
  const [slug, setSlug] = React.useState("")
  const [slugError, setSlugError] = React.useState("")
  const [resolved, setResolved] = React.useState<SsoResolution | null>(null)
  const [providerId, setProviderId] = React.useState("")
  const [redirected, setRedirected] = React.useState(false)
  const [password, setPassword] = React.useState("")
  const [passwordError, setPasswordError] = React.useState("")
  const [success, setSuccess] = React.useState(false)
  const resolving = useAsyncAction(text.failed)
  const orgResolving = useAsyncAction(text.failed)
  const sso = useAsyncAction(text.failed)
  const signing = useAsyncAction(text.failed)
  const titleRef = React.useRef<HTMLHeadingElement>(null)
  const slugRef = React.useRef<HTMLInputElement>(null)
  const retryRef = React.useRef<HTMLButtonElement>(null)
  const reduced = useReducedMotion()
  const id = React.useId()
  // 受控进入 sso 但还没有识别结果时，退回第一步
  const view: Auth04Step = step === "sso" && !resolved ? "email" : step
  const provider =
    resolved?.providers.find((item) => item.id === providerId) ??
    resolved?.providers[0]
  const previous = React.useRef({ view, success })
  React.useEffect(() => {
    if (previous.current.view !== view || previous.current.success !== success)
      titleRef.current?.focus()
    previous.current = { view, success }
  }, [view, success])
  React.useEffect(() => {
    if (sso.error) retryRef.current?.focus()
  }, [sso.error])
  React.useEffect(() => {
    if (orgOpen) slugRef.current?.focus()
  }, [orgOpen])

  function apply(result: Auth04Resolution, fromOrg: boolean) {
    sso.setError("")
    signing.setError("")
    setRedirected(false)
    setPassword("")
    setPasswordError("")
    if (result.kind === "sso" && result.providers.length > 0) {
      setResolved(result)
      setProviderId(result.providers[0]?.id ?? "")
      setIdentified(!fromOrg)
      setStep("sso")
    } else if (fromOrg) {
      // 组织标识只能走企业身份；普通账号需要邮箱，回到邮箱入口
      setSlugError(text.orgNoSso)
    } else {
      setResolved(null)
      setIdentified(true)
      setStep("password")
    }
  }
  async function submitEmail() {
    if (resolving.pending || orgResolving.pending) return
    const parsed = createEmailSchema(text).safeParse(email)
    if (!parsed.success) {
      setEmailError(parsed.error.issues[0]?.message ?? text.emailError)
      return
    }
    setEmail(parsed.data)
    const result = await resolving.run(() => onResolveDomain(parsed.data))
    if (result.ok) apply(result.value, false)
  }
  async function submitOrg() {
    if (!onResolveOrg || resolving.pending || orgResolving.pending) return
    const parsed = createSlugSchema(text).safeParse(slug)
    if (!parsed.success) {
      setSlugError(parsed.error.issues[0]?.message ?? text.orgError)
      return
    }
    setSlug(parsed.data)
    const result = await orgResolving.run(() => onResolveOrg(parsed.data))
    if (result.ok) apply(result.value, true)
  }
  async function signInSso(target: string) {
    if (sso.pending || redirected) return
    setProviderId(target)
    const result = await sso.run(() =>
      onSsoSignIn({ email: identified ? email : "", providerId: target }),
    )
    if (result.ok) setRedirected(true)
  }
  async function submitPassword() {
    if (signing.pending) return
    if (!identified) {
      const parsed = createEmailSchema(text).safeParse(email)
      if (!parsed.success) {
        setEmailError(parsed.error.issues[0]?.message ?? text.emailError)
        return
      }
    }
    if (!password) {
      setPasswordError(text.passwordRequired)
      return
    }
    const result = await signing.run(() =>
      onPasswordSignIn({ email: email.trim(), password }),
    )
    if (result.ok) {
      setSuccess(true)
      onSuccess?.()
    }
  }
  function changeEmail() {
    setStep("email")
    setPassword("")
    setPasswordError("")
    setEmailError("")
    signing.setError("")
    sso.setError("")
    setRedirected(false)
  }

  const titles = {
    email: text.emailTitle,
    sso: text.ssoTitle,
    password: text.passwordTitle,
  }
  return (
    <div
      data-slot="auth-04"
      data-step={view}
      data-state={success ? "success" : "idle"}
      className={cn(
        "w-full overflow-x-clip bg-background text-foreground",
        className,
      )}
      {...props}
    >
      <GridContainer className="max-w-4xl">
        <GridSection topLine className="px-4 py-6 sm:px-6">
          {brand && (
            <div className="mb-6 flex items-center gap-2 text-sm font-medium">
              {brand.logo}
              {brand.name}
            </div>
          )}
          <h1 className="text-2xl font-semibold tracking-tight">
            {text.title}
          </h1>
          <p className="mt-2 text-sm leading-7 text-muted-foreground">
            {text.description}
          </p>
        </GridSection>
        <GridSection>
          <div className="grid md:grid-cols-[minmax(0,1fr)_18rem] md:divide-x md:divide-dashed md:divide-edge">
            <div className="px-4 py-8 sm:px-6">
              <motion.div
                key={success ? "success" : view}
                data-slot="auth-04-step"
                initial={false}
                animate={
                  reduced
                    ? { opacity: 1, y: 0 }
                    : { opacity: [0.7, 1], y: [4, 0] }
                }
                transition={{ duration: reduced ? 0 : 0.18 }}
                className="mx-auto max-w-md md:mx-0 md:max-w-none"
              >
                <h2
                  ref={titleRef}
                  tabIndex={-1}
                  className="mb-5 text-lg font-medium outline-none focus-visible:underline"
                >
                  {success ? text.success : titles[view]}
                </h2>
                {success ? (
                  <p role="status" className="text-sm text-muted-foreground">
                    {text.successDescription}
                  </p>
                ) : view === "email" ? (
                  <Auth04EmailStep
                    id={id}
                    text={text}
                    email={email}
                    emailError={emailError || resolving.error}
                    resolving={resolving.pending}
                    orgEnabled={!!onResolveOrg}
                    orgOpen={orgOpen}
                    slug={slug}
                    slugError={slugError || orgResolving.error}
                    orgResolving={orgResolving.pending}
                    slugRef={slugRef}
                    onEmailChange={(value) => {
                      setEmail(value)
                      setEmailError("")
                      resolving.setError("")
                    }}
                    onSubmit={() => void submitEmail()}
                    onToggleOrg={() => setOrgOpen((open) => !open)}
                    onSlugChange={(value) => {
                      setSlug(value)
                      setSlugError("")
                      orgResolving.setError("")
                    }}
                    onSubmitOrg={() => void submitOrg()}
                  />
                ) : view === "sso" && resolved ? (
                  <Auth04SsoStep
                    text={text}
                    org={resolved.org}
                    providers={resolved.providers}
                    activeId={provider?.id ?? ""}
                    pending={sso.pending}
                    redirected={redirected}
                    error={sso.error}
                    retryRef={retryRef}
                    onSignIn={(target) => void signInSso(target)}
                    onRetry={() => void signInSso(provider?.id ?? "")}
                    onUsePassword={() => {
                      sso.setError("")
                      setStep("password")
                    }}
                    onChangeEmail={changeEmail}
                  />
                ) : (
                  <Auth04PasswordStep
                    id={id}
                    text={text}
                    email={email}
                    identified={identified}
                    emailError={emailError}
                    password={password}
                    passwordError={passwordError}
                    error={signing.error}
                    pending={signing.pending}
                    onEmailChange={(value) => {
                      setEmail(value)
                      setEmailError("")
                    }}
                    onPasswordChange={(value) => {
                      setPassword(value)
                      setPasswordError("")
                      signing.setError("")
                    }}
                    onSubmit={() => void submitPassword()}
                    onChangeEmail={changeEmail}
                  />
                )}
              </motion.div>
            </div>
            <Auth04Panel
              step={view}
              org={resolved?.org}
              provider={provider}
              text={text}
              className="max-md:order-first max-md:border-b max-md:border-dashed max-md:border-edge"
            />
          </div>
        </GridSection>
        <GridSection>
          <GridColumns>
            <div className="flex justify-center px-4 py-2">
              <Button
                type="button"
                variant="link"
                size="lg"
                onClick={() => onAlternative?.("personal")}
              >
                {text.personal}
              </Button>
            </div>
            <div className="flex justify-center px-4 py-2">
              <a
                href={supportHref}
                className={buttonVariants({ variant: "link", size: "lg" })}
              >
                {text.support}
              </a>
            </div>
          </GridColumns>
        </GridSection>
      </GridContainer>
    </div>
  )
}

export { Auth04 }
export type {
  Auth04Props,
  Auth04Step,
  Auth04Provider,
  Auth04Org,
  Auth04Resolution,
} from "./types"
export type { Auth04Labels } from "./config"

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }

"use client"

import * as React from "react"
import { Auth04 } from "@/components/auth-04/auth-04"
import type { Auth04Resolution } from "@/components/auth-04/types"

const wait = () => new Promise((resolve) => setTimeout(resolve, 350))

const YUNJIAN: Auth04Resolution = {
  kind: "sso",
  org: { name: "云间科技", domain: "yunjian.example" },
  providers: [{ id: "saml", label: "企业身份（SAML）", protocol: "saml" }],
}

const MULTI: Auth04Resolution = {
  kind: "sso",
  org: { name: "多域集团", domain: "multi.example" },
  providers: [
    { id: "saml", label: "企业身份（SAML）", protocol: "saml" },
    { id: "oidc", label: "企业身份（OIDC）", protocol: "oidc" },
  ],
}

/** 演示后端仅用于体验界面，接入时替换为真实的域名识别、SSO 与认证服务。 */
export default function LoginPage() {
  const [notice, setNotice] = React.useState("")
  return (
    <main
      data-slot="auth-04-demo"
      className="flex min-h-screen flex-col justify-center bg-background px-4 py-8 text-foreground"
    >
      <div className="mx-auto mb-4 max-w-2xl space-y-1 text-center text-xs leading-6 text-muted-foreground">
        <p>
          <span className="font-mono">@yunjian.example</span> 识别为云间科技，
          <span className="font-mono">@multi.example</span> 有两个提供方，
          <span className="font-mono">@fail.example</span> 的 SSO 跳转会失败。
        </p>
        <p>
          其他邮箱走账号密码，演示密码{" "}
          <span className="font-mono">demo1234</span>
          ；组织标识 <span className="font-mono">yunjian</span> 可识别。
        </p>
      </div>
      <Auth04
        brand={{ name: "云间工作台" }}
        supportHref="mailto:admin@yunjian.example"
        onResolveDomain={async (email) => {
          await wait()
          const domain = email.split("@")[1]?.toLowerCase() ?? ""
          if (domain === "yunjian.example") return YUNJIAN
          if (domain === "multi.example") return MULTI
          if (domain === "fail.example")
            return {
              kind: "sso",
              org: { name: "故障演示", domain: "fail.example" },
              providers: [
                { id: "saml", label: "企业身份（SAML）", protocol: "saml" },
              ],
            }
          return { kind: "password" }
        }}
        onResolveOrg={async (slug) => {
          await wait()
          if (slug === "yunjian") return YUNJIAN
          throw new Error("未找到该组织，请检查组织标识")
        }}
        onSsoSignIn={async ({ email }) => {
          await wait()
          if (email.endsWith("@fail.example"))
            throw new Error("无法连接到企业身份提供方，请稍后重试")
        }}
        onPasswordSignIn={async ({ password }) => {
          await wait()
          if (password !== "demo1234")
            throw new Error("邮箱或密码不正确，请重试")
        }}
        onAlternative={() => setNotice("请在接入后打开个人账号登录页面")}
      />
      <p
        role="status"
        className="mt-4 text-center text-xs text-muted-foreground"
      >
        {notice}
      </p>
    </main>
  )
}

import { z } from "zod"
import type { Auth04Labels } from "./config"

function createEmailSchema(labels: Auth04Labels) {
  return z
    .string()
    .trim()
    .regex(/^[^\s@]+@[^\s@]+\.[^\s@]+$/, labels.emailError)
}

function createSlugSchema(labels: Auth04Labels) {
  return z
    .string()
    .trim()
    .toLowerCase()
    .regex(/^[a-z0-9][a-z0-9-]*$/, labels.orgError)
}

export { createEmailSchema, createSlugSchema }

import type * as React from "react"
import type { Auth04Labels } from "./config"

type Auth04Step = "email" | "sso" | "password"

/** 企业身份提供方；`label` 直接显示在按钮上，请使用通用叫法。 */
type Auth04Provider = {
  id: string
  /** 例如「企业身份（SAML）」 */
  label: string
  /** 协议类型，决定默认图标 */
  protocol?: "saml" | "oidc" | "directory"
  /** 自定义图标，覆盖 `protocol` 的默认图标 */
  icon?: React.ReactNode
}

type Auth04Org = {
  name: string
  /** 企业邮箱域名，例如 yunjian.example */
  domain: string
  logo?: React.ReactNode
}

/** 域名或组织标识的识别结果。 */
type Auth04Resolution =
  | { kind: "sso"; org: Auth04Org; providers: Auth04Provider[] }
  | { kind: "password" }

type Auth04Props = Omit<React.ComponentProps<"div">, "onSuccess"> & {
  /** 根据工作邮箱识别登录方式；失败时抛出 Error，信息显示在邮箱框下。 */
  onResolveDomain: (email: string) => Promise<Auth04Resolution>
  /** 根据组织标识识别；不传则隐藏「使用组织标识登录」。 */
  onResolveOrg?: (slug: string) => Promise<Auth04Resolution>
  /**
   * 发起企业单点登录，成功后由接入方负责跳转。
   * 通过组织标识进入时没有邮箱，`email` 为空字符串。
   */
  onSsoSignIn: (values: { email: string; providerId: string }) => Promise<void>
  /** 账号密码登录，失败时抛出 Error。 */
  onPasswordSignIn: (values: {
    email: string
    password: string
  }) => Promise<void>
  /** 密码登录成功后的通知。 */
  onSuccess?: () => void
  /** 其他登录入口，由接入方处理导航。 */
  onAlternative?: (method: "personal") => void
  /** 「联系管理员」链接。@default "#" */
  supportHref?: string
  /** 品牌名称和标志。 */
  brand?: { name: string; logo?: React.ReactNode }
  /** 覆盖默认中文文案。 */
  labels?: Partial<Auth04Labels>
  /** 受控步骤。 */
  step?: Auth04Step
  /** 初始步骤。@default "email" */
  defaultStep?: Auth04Step
  /** 步骤变化通知。 */
  onStepChange?: (step: Auth04Step) => void
}

export type {
  Auth04Org,
  Auth04Props,
  Auth04Provider,
  Auth04Resolution,
  Auth04Step,
}

"use client"

import * as React from "react"

type AsyncResult<T> = { ok: true; value: T } | { ok: false }

/** 用同步锁拦截回车与连点造成的重复请求，并返回回调的结果。 */
function useAsyncAction(fallback: string) {
  const lock = React.useRef(false)
  const [pending, setPending] = React.useState(false)
  const [error, setError] = React.useState("")
  async function run<T>(action: () => Promise<T>): Promise<AsyncResult<T>> {
    if (lock.current) return { ok: false }
    lock.current = true
    setPending(true)
    setError("")
    try {
      return { ok: true, value: await action() }
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : fallback)
      return { ok: false }
    } finally {
      lock.current = false
      setPending(false)
    }
  }
  return { pending, error, setError, run }
}

export { useAsyncAction }

"use client"

import * as React from "react"
import {
  Building2,
  Eye,
  EyeOff,
  KeyRound,
  Loader2,
  ShieldCheck,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { cn } from "@/lib/utils"
import type { Auth04Provider } from "./types"

/** 输入框统一取 lg 档：桌面 36px，触屏 44px，与同一表单里的 lg 按钮等高。 */
const INPUT_CLASS = "h-9 pointer-coarse:h-11"

/** 带标签、提示和错误文字的输入框；错误通过 aria-describedby 关联。 */
function Auth04Field({
  label,
  hint,
  error,
  trailing,
  className,
  id,
  ...props
}: Omit<React.ComponentProps<"input">, "size"> & {
  id: string
  label: string
  hint?: string
  error?: string
  /** 输入框内最右侧的元素，例如显示密码按钮 */
  trailing?: React.ReactNode
}) {
  const describedBy =
    [hint && `${id}-hint`, error && `${id}-error`].filter(Boolean).join(" ") ||
    undefined
  return (
    <div data-slot="auth-04-field" className="space-y-2">
      <Label htmlFor={id}>{label}</Label>
      <div className="relative">
        <Input
          {...props}
          id={id}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          className={cn(INPUT_CLASS, trailing && "pr-11", className)}
        />
        {trailing && (
          <span className="absolute inset-y-0 right-0.5 flex items-center">
            {trailing}
          </span>
        )}
      </div>
      {hint && (
        <p id={`${id}-hint`} className="text-xs text-muted-foreground">
          {hint}
        </p>
      )}
      {error && (
        <p id={`${id}-error`} role="alert" className="text-xs text-destructive">
          {error}
        </p>
      )}
    </div>
  )
}

/** 带显示/隐藏切换的密码框。 */
function Auth04PasswordField({
  showLabel,
  hideLabel,
  ...props
}: Omit<React.ComponentProps<typeof Auth04Field>, "type" | "trailing"> & {
  showLabel: string
  hideLabel: string
}) {
  const [visible, setVisible] = React.useState(false)
  return (
    <Auth04Field
      {...props}
      type={visible ? "text" : "password"}
      trailing={
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label={visible ? hideLabel : showLabel}
          aria-pressed={visible}
          onClick={() => setVisible((value) => !value)}
          className="text-muted-foreground hover:text-foreground"
        >
          {visible ? <EyeOff aria-hidden="true" /> : <Eye aria-hidden="true" />}
        </Button>
      }
    />
  )
}

/** 表单级错误，出现时读屏立即朗读。 */
function Auth04Error({
  children,
  id,
}: {
  children: React.ReactNode
  id?: string
}) {
  return (
    <p
      id={id}
      data-slot="auth-04-error"
      role="alert"
      className="rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive"
    >
      {children}
    </p>
  )
}

/** 提供方默认图标：按协议区分，调用方可用 `icon` 覆盖。 */
function providerIcon(provider: Auth04Provider) {
  if (provider.icon) return provider.icon
  if (provider.protocol === "oidc") return <KeyRound aria-hidden="true" />
  if (provider.protocol === "directory") return <Building2 aria-hidden="true" />
  return <ShieldCheck aria-hidden="true" />
}

/** 提供方登录按钮；进行中显示转圈，宽度不变。 */
function Auth04ProviderButton({
  provider,
  text,
  primary,
  pending,
  disabled,
  onClick,
}: {
  provider: Auth04Provider
  text: string
  primary: boolean
  pending: boolean
  disabled: boolean
  onClick: () => void
}) {
  return (
    <Button
      type="button"
      size="lg"
      variant={primary ? "default" : "outline"}
      data-slot="auth-04-provider"
      data-provider={provider.id}
      className="w-full"
      disabled={disabled}
      onClick={onClick}
    >
      {pending ? (
        <Loader2 aria-hidden="true" className="animate-spin" />
      ) : (
        providerIcon(provider)
      )}
      {text}
    </Button>
  )
}

export {
  Auth04Error,
  Auth04Field,
  Auth04PasswordField,
  Auth04ProviderButton,
  providerIcon,
}

"use client"

import * as React from "react"
import { Building2, Loader2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import { formatLabel, type Auth04Labels } from "./config"
import {
  Auth04Error,
  Auth04Field,
  Auth04PasswordField,
  Auth04ProviderButton,
} from "./form-parts"
import type { Auth04Org, Auth04Provider } from "./types"

/** 例外：行内文字链接，高度跟随文字，不占按钮的三档高度。 */
const INLINE_LINK = "h-auto px-0 pointer-coarse:h-auto"

function Auth04EmailStep({
  id,
  text,
  email,
  emailError,
  resolving,
  orgEnabled,
  orgOpen,
  slug,
  slugError,
  orgResolving,
  slugRef,
  onEmailChange,
  onSubmit,
  onToggleOrg,
  onSlugChange,
  onSubmitOrg,
}: {
  id: string
  text: Auth04Labels
  email: string
  emailError: string
  resolving: boolean
  orgEnabled: boolean
  orgOpen: boolean
  slug: string
  slugError: string
  orgResolving: boolean
  slugRef: React.Ref<HTMLInputElement>
  onEmailChange: (value: string) => void
  onSubmit: () => void
  onToggleOrg: () => void
  onSlugChange: (value: string) => void
  onSubmitOrg: () => void
}) {
  const busy = resolving || orgResolving
  return (
    <div data-slot="auth-04-email-step" className="space-y-6">
      <form
        noValidate
        onSubmit={(event) => {
          event.preventDefault()
          onSubmit()
        }}
        className="space-y-5"
      >
        <Auth04Field
          id={`${id}-email`}
          label={text.email}
          type="email"
          name="email"
          autoComplete="username"
          autoCapitalize="none"
          spellCheck={false}
          placeholder={text.emailPlaceholder}
          value={email}
          error={emailError}
          disabled={busy}
          onChange={(event) => onEmailChange(event.target.value)}
        />
        <Button type="submit" size="lg" className="w-full" disabled={busy}>
          {resolving && <Loader2 aria-hidden="true" className="animate-spin" />}
          {resolving ? text.resolving : text.continue}
        </Button>
      </form>
      {orgEnabled && (
        <div className="space-y-4 border-t border-dashed border-edge pt-4">
          <Button
            type="button"
            variant="link"
            size="sm"
            className={INLINE_LINK}
            aria-expanded={orgOpen}
            aria-controls={`${id}-org`}
            disabled={busy}
            onClick={onToggleOrg}
          >
            {text.orgToggle}
          </Button>
          {orgOpen && (
            <form
              id={`${id}-org`}
              noValidate
              onSubmit={(event) => {
                event.preventDefault()
                onSubmitOrg()
              }}
              className="space-y-5"
            >
              <Auth04Field
                id={`${id}-slug`}
                label={text.orgSlug}
                hint={text.orgHint}
                name="organization"
                autoComplete="organization"
                autoCapitalize="none"
                spellCheck={false}
                value={slug}
                error={slugError}
                disabled={busy}
                ref={slugRef}
                onChange={(event) => onSlugChange(event.target.value)}
              />
              <Button
                type="submit"
                size="lg"
                variant="outline"
                className="w-full"
                disabled={busy}
              >
                {orgResolving && (
                  <Loader2 aria-hidden="true" className="animate-spin" />
                )}
                {orgResolving ? text.resolving : text.continue}
              </Button>
            </form>
          )}
        </div>
      )}
    </div>
  )
}

function Auth04SsoStep({
  text,
  org,
  providers,
  activeId,
  pending,
  redirected,
  error,
  retryRef,
  onSignIn,
  onRetry,
  onUsePassword,
  onChangeEmail,
}: {
  text: Auth04Labels
  org: Auth04Org
  providers: Auth04Provider[]
  activeId: string
  pending: boolean
  redirected: boolean
  error: string
  retryRef: React.Ref<HTMLButtonElement>
  onSignIn: (providerId: string) => void
  onRetry: () => void
  onUsePassword: () => void
  onChangeEmail: () => void
}) {
  const busy = pending || redirected
  return (
    <div data-slot="auth-04-sso-step" className="space-y-5">
      {/* 宽屏右栏的组织面板已显示组织名和域名，这张卡只在窄屏出现，避免重复 */}
      <div
        data-slot="auth-04-org-card"
        className="flex items-center gap-3 rounded-lg border border-edge bg-muted/30 p-3 md:hidden"
      >
        <span className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-md border border-edge bg-background [&_svg]:size-5">
          {org.logo ?? <Building2 aria-hidden="true" />}
        </span>
        <div className="min-w-0">
          <p className="truncate text-sm font-medium">{org.name}</p>
          <p className="truncate font-mono text-xs text-muted-foreground">
            {org.domain}
          </p>
        </div>
      </div>
      <p className="text-sm leading-7 text-muted-foreground">
        {formatLabel(text.identified, { org: org.name })}
      </p>
      <div className="space-y-3">
        {providers.map((provider) => (
          <Auth04ProviderButton
            key={provider.id}
            provider={provider}
            primary={providers.length === 1}
            text={formatLabel(text.signInWith, { provider: provider.label })}
            pending={busy && provider.id === activeId}
            disabled={busy}
            onClick={() => onSignIn(provider.id)}
          />
        ))}
      </div>
      {busy && !error && (
        <p role="status" className="text-sm text-muted-foreground">
          {text.redirecting}
        </p>
      )}
      {error && (
        <div className="space-y-3">
          <Auth04Error>{error}</Auth04Error>
          <div className="flex flex-col gap-2 sm:flex-row">
            <Button
              ref={retryRef}
              type="button"
              size="lg"
              variant="outline"
              className="sm:flex-1"
              disabled={busy}
              onClick={onRetry}
            >
              {text.retry}
            </Button>
            <Button
              type="button"
              size="lg"
              variant="ghost"
              className="sm:flex-1"
              disabled={busy}
              onClick={onUsePassword}
            >
              {text.usePassword}
            </Button>
          </div>
        </div>
      )}
      <Button
        type="button"
        variant="link"
        size="sm"
        className={INLINE_LINK}
        disabled={busy}
        onClick={onChangeEmail}
      >
        {text.notThisOrg}
      </Button>
    </div>
  )
}

function Auth04PasswordStep({
  id,
  text,
  email,
  identified,
  emailError,
  password,
  passwordError,
  error,
  pending,
  onEmailChange,
  onPasswordChange,
  onSubmit,
  onChangeEmail,
}: {
  id: string
  text: Auth04Labels
  email: string
  /** 邮箱已由域名识别确认，只读展示；否则（经组织标识进入）显示输入框 */
  identified: boolean
  emailError: string
  password: string
  passwordError: string
  error: string
  pending: boolean
  onEmailChange: (value: string) => void
  onPasswordChange: (value: string) => void
  onSubmit: () => void
  onChangeEmail: () => void
}) {
  return (
    <form
      data-slot="auth-04-password-step"
      noValidate
      onSubmit={(event) => {
        event.preventDefault()
        onSubmit()
      }}
      className="space-y-5"
    >
      {identified ? (
        <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1 text-sm">
          <p className="min-w-0 break-all">
            <span className="text-muted-foreground">{text.signingInAs} </span>
            <span className="font-mono">{email}</span>
          </p>
          <Button
            type="button"
            variant="link"
            size="sm"
            className={INLINE_LINK}
            disabled={pending}
            onClick={onChangeEmail}
          >
            {text.change}
          </Button>
        </div>
      ) : (
        <Auth04Field
          id={`${id}-email`}
          label={text.email}
          type="email"
          name="email"
          autoComplete="username"
          autoCapitalize="none"
          spellCheck={false}
          placeholder={text.emailPlaceholder}
          value={email}
          error={emailError}
          disabled={pending}
          onChange={(event) => onEmailChange(event.target.value)}
        />
      )}
      <Auth04PasswordField
        id={`${id}-password`}
        label={text.password}
        name="password"
        autoComplete="current-password"
        value={password}
        error={passwordError}
        disabled={pending}
        showLabel={text.showPassword}
        hideLabel={text.hidePassword}
        onChange={(event) => onPasswordChange(event.target.value)}
      />
      {error && <Auth04Error>{error}</Auth04Error>}
      <Button type="submit" size="lg" className="w-full" disabled={pending}>
        {pending && <Loader2 aria-hidden="true" className="animate-spin" />}
        {pending ? text.signingIn : text.signIn}
      </Button>
    </form>
  )
}

export { Auth04EmailStep, Auth04PasswordStep, Auth04SsoStep }

import { Building2, ShieldCheck } from "lucide-react"
import { cn } from "@/lib/utils"
import type { Auth04Labels } from "./config"
import { providerIcon } from "./form-parts"
import type { Auth04Org, Auth04Provider, Auth04Step } from "./types"

/**
 * 右侧组织面板：第一步说明识别规则，识别后展示组织、所选提供方和安全提示。
 * 窄屏缩成表单上方的紧凑卡片；第一步没有组织信息，窄屏隐藏。
 */
function Auth04Panel({
  step,
  org,
  provider,
  text,
  className,
}: {
  step: Auth04Step
  org?: Auth04Org
  provider?: Auth04Provider
  text: Auth04Labels
  className?: string
}) {
  const identified = step === "sso" && org
  return (
    <aside
      data-slot="auth-04-panel"
      data-step={step}
      aria-label={text.panelLabel}
      className={cn(
        "bg-muted/30 px-4 py-4 sm:px-6 md:py-8",
        step === "email" && "max-md:hidden",
        className,
      )}
    >
      {identified ? (
        <div className="space-y-3 md:space-y-5">
          <dl className="space-y-4 text-sm max-md:hidden">
            <div className="flex items-center gap-3">
              <span className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-md border border-edge bg-background [&_svg]:size-5">
                {org.logo ?? <Building2 aria-hidden="true" />}
              </span>
              <div className="min-w-0">
                <dt className="sr-only">{text.orgName}</dt>
                <dd className="truncate font-medium">{org.name}</dd>
                <dt className="sr-only">{text.orgDomain}</dt>
                <dd className="truncate font-mono text-xs text-muted-foreground">
                  {org.domain}
                </dd>
              </div>
            </div>
            {provider && (
              <div className="border-t border-dashed border-edge pt-4">
                <dt className="text-xs text-muted-foreground">
                  {text.orgProvider}
                </dt>
                <dd className="mt-1 flex items-center gap-2 [&_svg]:size-4 [&_svg]:shrink-0">
                  {providerIcon(provider)}
                  {provider.label}
                </dd>
              </div>
            )}
          </dl>
          {provider && (
            <p className="flex items-center gap-2 text-sm font-medium md:hidden [&_svg]:size-4 [&_svg]:shrink-0">
              {providerIcon(provider)}
              {provider.label}
            </p>
          )}
          <p className="flex items-start gap-2 text-xs leading-6 text-muted-foreground max-md:text-sm">
            <ShieldCheck
              aria-hidden="true"
              className="mt-1 size-4 shrink-0 text-foreground"
            />
            <span>{text.security}</span>
          </p>
        </div>
      ) : step === "password" ? (
        <div className="space-y-2">
          <h2 className="text-sm font-medium">{text.passwordPanelTitle}</h2>
          <p className="text-xs leading-6 text-muted-foreground max-md:text-sm">
            {text.passwordPanelDescription}
          </p>
        </div>
      ) : (
        <div className="space-y-5">
          <div className="space-y-2">
            <h2 className="text-sm font-medium">{text.panelTitle}</h2>
            <p className="text-sm leading-7 text-muted-foreground">
              {text.panelDescription}
            </p>
          </div>
          <div className="space-y-3">
            <h3 className="text-xs text-muted-foreground">
              {text.methodsTitle}
            </h3>
            <ul className="space-y-2 text-sm">
              {[text.methodSso, text.methodDirectory, text.methodPassword].map(
                (item) => (
                  <li key={item} className="flex items-center gap-2">
                    <span
                      aria-hidden="true"
                      className="size-1.5 shrink-0 bg-primary"
                    />
                    {item}
                  </li>
                ),
              )}
            </ul>
          </div>
        </div>
      )}
    </aside>
  )
}

export { Auth04Panel }
